using CTXD.Server.Data;
using CTXD.Server.Domain;
using CTXD.Server.Models;
using Npgsql;

namespace CTXD.Server.Services;

public sealed class NationProgressService(GameDb db, CanonicalContent content, ExperienceService experience,IPlayerItemInventory items,DragonActivityService dragon,IronActivityService ironActivity)
{
    static readonly int[] TrialCities = [0, 251, 250, 252];
    public async Task<NationTrialView> GetTrialAsync(long playerId, CancellationToken ct)
    { await using var c = await db.DataSource.OpenConnectionAsync(ct); var force = await ForceAsync(c, null, playerId, ct); await ExpireTrialAsync(c, null, force, ct); int id, stage, kills; DateTimeOffset? end; bool won; await using (var cmd = new NpgsqlCommand("SELECT trial_id,stage,trial_general_kills,trial_ends_at,trial_won FROM nation_forces WHERE force_id=$1", c)) { cmd.Parameters.AddWithValue(force); await using var r = await cmd.ExecuteReaderAsync(ct); await r.ReadAsync(ct); id = r.GetInt32(0); stage = r.GetInt16(1); kills = r.GetInt32(2); end = r.IsDBNull(3) ? null : r.GetFieldValue<DateTimeOffset>(3); won = r.GetBoolean(4); } var playerKills = await PlayerValueAsync(c, null, playerId, "trial_kills", ct); var rank = await RankAsync(c, null, force, "trial_kills", playerId, ct); var reward = await RewardFlagAsync(c, null, playerId, "trial_received", ct); content.CdExams.TryGetValue(id, out var exam); return new(force, id, stage, end, won, playerKills, rank, TrialCities[force], exam?.DisplayName ?? "", exam is null ? [] : [new(1, exam.General1), new(2, exam.General2), new(3, exam.General3)], won && playerKills > 0 && !reward); }

    public async Task<NationTrialView> StartTrialAsync(long playerId, CancellationToken ct)
    {
        await using var c = await db.DataSource.OpenConnectionAsync(ct); await using var t = await c.BeginTransactionAsync(ct); var force = await ForceAsync(c, t, playerId, ct); var hour = DateTime.Now.Hour; if (hour < 8) throw new GameException("TRIAL_TIME_FORBIDDEN", "Nation trial cannot open between 00:00 and 08:00 legacy server time."); int officialId, building = 0; await using (var p = new NpgsqlCommand("SELECT official_id FROM players WHERE id=$1 FOR UPDATE", c, t)) { p.Parameters.AddWithValue(playerId); officialId = Convert.ToInt32(await p.ExecuteScalarAsync(ct)); }
        await using (var m = new NpgsqlCommand("SELECT building_id FROM player_office_memberships WHERE player_id=$1 AND state=1", c, t)) { m.Parameters.AddWithValue(playerId); var x = await m.ExecuteScalarAsync(ct); if (x is not null) building = Convert.ToInt32(x); }
        if (building == 0 || !content.Halls.TryGetValue((building, 1), out var hall) || hall.OfficialId > 2 || officialId != hall.OfficialId) throw new GameException("TRIAL_OFFICIAL_FORBIDDEN", "Only the king or legacy first-rank official may open the trial.", 403);
        int level, stage; long exp; DateTimeOffset? trialEnd, taskEnd; string ids; await using (var f = new NpgsqlCommand("SELECT level,exp,stage,trial_ends_at,task_ends_at,trial_attempt_ids FROM nation_forces WHERE force_id=$1 FOR UPDATE", c, t)) { f.Parameters.AddWithValue(force); await using var r = await f.ExecuteReaderAsync(ct); await r.ReadAsync(ct); level = r.GetInt32(0); exp = r.GetInt64(1); stage = r.GetInt16(2); trialEnd = r.IsDBNull(3) ? null : r.GetFieldValue<DateTimeOffset>(3); taskEnd = r.IsDBNull(4) ? null : r.GetFieldValue<DateTimeOffset>(4); ids = r.GetString(5); }
        var now = DateTimeOffset.UtcNow; if (stage < 4 && trialEnd > now) throw new GameException("TRIAL_ACTIVE", "Nation trial is already active."); if (trialEnd.HasValue && trialEnd.Value.AddHours(3) > now) throw new GameException("TRIAL_COOLDOWN", "Nation trial is in the legacy three-hour post-end cooldown."); if (taskEnd > now) throw new GameException("NATION_TASK_ACTIVE", "Nation task is active."); await using (var other = new NpgsqlCommand("SELECT 1 FROM nation_forces WHERE force_id<>$1 AND stage<4 AND trial_ends_at>now()", c, t)) { other.Parameters.AddWithValue(force); if (await other.ExecuteScalarAsync(ct) is not null) throw new GameException("OTHER_TRIAL_ACTIVE", "Another nation trial is active."); }
        var list = ids.Split(';', StringSplitOptions.RemoveEmptyEntries).Select(int.Parse).ToList(); if (list.Count == 0) throw new GameException("TRIAL_NO_ATTEMPTS", "No nation trial attempts remain."); var id = list[0]; if (!content.CdExams.TryGetValue(id, out var exam)) throw new GameException("TRIAL_STATIC_MISSING", "Trial static definition is missing.", 500); list.RemoveAt(0); var end = now.AddHours(2); await using (var reset = new NpgsqlCommand("UPDATE nation_forces SET trial_id=$2,stage=0,trial_general_kills=0,trial_ends_at=$3,trial_won=false,trial_attempt_ids=$4,updated_at=now() WHERE force_id=$1;DELETE FROM nation_trial_npcs WHERE force_id=$1;UPDATE player_nation_ranks SET trial_kills=0,trial_received=true WHERE force_id=$1", c, t)) { reset.Parameters.AddWithValue(force); reset.Parameters.AddWithValue(id); reset.Parameters.AddWithValue(end); reset.Parameters.AddWithValue(string.Join(';', list)); await reset.ExecuteNonQueryAsync(ct); }
        await SpawnStageAsync(c, t, force, exam, 0, ct); await t.CommitAsync(ct); return await GetTrialAsync(playerId, ct);
    }

    public async Task<long> StartTrialBattleAsync(long playerId, int cityId, int generalId, CancellationToken ct)
    { await using var c = await db.DataSource.OpenConnectionAsync(ct); await using var t = await c.BeginTransactionAsync(ct); var force = await ForceAsync(c, t, playerId, ct); int stage; DateTimeOffset? end; await using (var trial = new NpgsqlCommand("SELECT stage,trial_ends_at FROM nation_forces WHERE force_id=$1 FOR UPDATE", c, t)) { trial.Parameters.AddWithValue(force); await using var r = await trial.ExecuteReaderAsync(ct); await r.ReadAsync(ct); stage = r.GetInt16(0); end = r.IsDBNull(1) ? null : r.GetFieldValue<DateTimeOffset>(1); } if (stage >= 4 || end <= DateTimeOffset.UtcNow) throw new GameException("TRIAL_NOT_ACTIVE", "Nation trial is not active."); await using (var npc = new NpgsqlCommand("SELECT 1 FROM nation_trial_npcs WHERE force_id=$1 AND city_id=$2 AND stage=$3 AND defeated=false", c, t)) { npc.Parameters.AddWithValue(force); npc.Parameters.AddWithValue(cityId); npc.Parameters.AddWithValue(stage); if (await npc.ExecuteScalarAsync(ct) is null) throw new GameException("TRIAL_CITY_INACTIVE", "This city has no active trial army."); } await using (var general = new NpgsqlCommand("SELECT 1 FROM player_generals WHERE player_id=$1 AND general_id=$2 AND general_type=2 AND location_id=$3 AND state<=1 AND forces>0 FOR UPDATE", c, t)) { general.Parameters.AddWithValue(playerId); general.Parameters.AddWithValue(generalId); general.Parameters.AddWithValue(cityId); if (await general.ExecuteScalarAsync(ct) is null) throw new GameException("TRIAL_GENERAL_INVALID", "General cannot enter this trial battle."); } await using (var active = new NpgsqlCommand("SELECT id FROM world_battle_handoffs WHERE city_id=$1 AND battle_type=14 AND status=0", c, t)) { active.Parameters.AddWithValue(cityId); var existing = await active.ExecuteScalarAsync(ct); if (existing is not null) { await t.CommitAsync(ct); return Convert.ToInt64(existing); } } long id; await using (var add = new NpgsqlCommand("INSERT INTO world_battle_handoffs(city_id,attacker_player_id,attacker_general_id,attacker_force_id,defender_force_id,battle_type) VALUES($1,$2,$3,$4,$5,14) RETURNING id", c, t)) { add.Parameters.AddWithValue(cityId); add.Parameters.AddWithValue(playerId); add.Parameters.AddWithValue(generalId); add.Parameters.AddWithValue(force); add.Parameters.AddWithValue(100 + force); id = Convert.ToInt64(await add.ExecuteScalarAsync(ct)); } await using (var state = new NpgsqlCommand("UPDATE player_generals SET state=3,updated_at=now() WHERE player_id=$1 AND general_id=$2", c, t)) { state.Parameters.AddWithValue(playerId); state.Parameters.AddWithValue(generalId); await state.ExecuteNonQueryAsync(ct); } await t.CommitAsync(ct); return id; }

    public async Task<int> ResolveBattleCityAsync(long playerId,bool task,CancellationToken ct)
    {await using var c=await db.DataSource.OpenConnectionAsync(ct);var force=await ForceAsync(c,null,playerId,ct);var sql=task?"SELECT city_id FROM nation_task_npcs WHERE force_id=$1 AND defeated=false ORDER BY id LIMIT 1":"SELECT city_id FROM nation_trial_npcs n JOIN nation_forces f ON f.force_id=n.force_id AND f.stage=n.stage WHERE n.force_id=$1 AND n.defeated=false ORDER BY n.id LIMIT 1";await using var cmd=new NpgsqlCommand(sql,c);cmd.Parameters.AddWithValue(force);var city=await cmd.ExecuteScalarAsync(ct);if(city is null)throw new GameException("NATION_BATTLE_CITY_MISSING","No active Nation battle city.");return Convert.ToInt32(city);}

    public async Task<long> StartTaskBattleAsync(long playerId,int cityId,int generalId,CancellationToken ct)
    {await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);var force=await ForceAsync(c,t,playerId,ct);await using(var npc=new NpgsqlCommand("SELECT 1 FROM nation_task_npcs WHERE force_id=$1 AND city_id=$2 AND defeated=false",c,t)){npc.Parameters.AddWithValue(force);npc.Parameters.AddWithValue(cityId);if(await npc.ExecuteScalarAsync(ct)is null)throw new GameException("NATION_TASK_CITY_INACTIVE","This city has no active nation-task army.");}await using(var general=new NpgsqlCommand("SELECT 1 FROM player_generals WHERE player_id=$1 AND general_id=$2 AND general_type=2 AND location_id=$3 AND state<=1 AND forces>0 FOR UPDATE",c,t)){general.Parameters.AddWithValue(playerId);general.Parameters.AddWithValue(generalId);general.Parameters.AddWithValue(cityId);if(await general.ExecuteScalarAsync(ct)is null)throw new GameException("NATION_TASK_GENERAL_INVALID","General cannot enter this nation-task battle.");}long id;await using(var add=new NpgsqlCommand("INSERT INTO world_battle_handoffs(city_id,attacker_player_id,attacker_general_id,attacker_force_id,defender_force_id,battle_type) VALUES($1,$2,$3,$4,$5,14) RETURNING id",c,t)){add.Parameters.AddWithValue(cityId);add.Parameters.AddWithValue(playerId);add.Parameters.AddWithValue(generalId);add.Parameters.AddWithValue(force);add.Parameters.AddWithValue(100+force);id=Convert.ToInt64(await add.ExecuteScalarAsync(ct));}await using(var state=new NpgsqlCommand("UPDATE player_generals SET state=3,updated_at=now() WHERE player_id=$1 AND general_id=$2",c,t)){state.Parameters.AddWithValue(playerId);state.Parameters.AddWithValue(generalId);await state.ExecuteNonQueryAsync(ct);}await t.CommitAsync(ct);return id;}

    public async Task<NationTrialReward> ClaimTrialRewardAsync(long playerId, CancellationToken ct)
    { await using var c = await db.DataSource.OpenConnectionAsync(ct); await using var t = await c.BeginTransactionAsync(ct); var force = await ForceAsync(c, t, playerId, ct); int id; bool won; await using (var f = new NpgsqlCommand("SELECT trial_id,trial_won FROM nation_forces WHERE force_id=$1 FOR UPDATE", c, t)) { f.Parameters.AddWithValue(force); await using var r = await f.ExecuteReaderAsync(ct); await r.ReadAsync(ct); id = r.GetInt32(0); won = r.GetBoolean(1); } if (!won || !content.CdExams.TryGetValue(id, out var exam)) throw new GameException("TRIAL_NOT_WON", "Nation trial has not been won."); int kills; bool received; await using (var p = new NpgsqlCommand("SELECT trial_kills,trial_received FROM player_nation_ranks WHERE player_id=$1 FOR UPDATE", c, t)) { p.Parameters.AddWithValue(playerId); await using var r = await p.ExecuteReaderAsync(ct); if (!await r.ReadAsync(ct)) throw new GameException("TRIAL_NOT_JOINED", "Player did not join the trial."); kills = r.GetInt32(0); received = r.GetBoolean(1); } if (kills <= 0) throw new GameException("TRIAL_NOT_JOINED", "Player did not join the trial."); if (received) throw new GameException("TRIAL_REWARD_RECEIVED", "Trial reward was already received."); var rank = await RankAsync(c, t, force, "trial_kills", playerId, ct); var rate = content.CdExamRankings.FirstOrDefault(x => x.High <= rank && rank <= x.Low)?.E ?? 0; var rankExp = (int)(exam.RankingExp * rate); var rankIron = (int)(exam.RankingIron * rate); await experience.AddAsync(c, t, playerId, exam.WinExp + rankExp, ct); await using (var reward = new NpgsqlCommand("UPDATE player_resources SET iron=iron+$2 WHERE player_id=$1;UPDATE player_nation_ranks SET trial_received=true WHERE player_id=$1", c, t)) { reward.Parameters.AddWithValue(playerId); reward.Parameters.AddWithValue(exam.WinIron + rankIron); await reward.ExecuteNonQueryAsync(ct); } await ironActivity.RecordGainAsync(c,t,playerId,exam.WinIron+rankIron,ct);await t.CommitAsync(ct); return new(exam.WinExp, exam.WinIron, rankExp, rankIron); }

    public async Task<IReadOnlyList<NationRankEntry>> GetRankAsync(long playerId, string kind, CancellationToken ct)
    { var column = kind switch { "trial" => "trial_kills", "protect" => "protect_kills", "task" => "task_score", _ => throw new GameException("RANK_KIND_INVALID", "Unknown nation rank.") }; await using var c = await db.DataSource.OpenConnectionAsync(ct); var force = await ForceAsync(c, null, playerId, ct); var result = new List<NationRankEntry>(); await using var cmd = new NpgsqlCommand($"SELECT r.player_id,COALESCE(p.display_name,''),r.{column} FROM player_nation_ranks r JOIN players p ON p.id=r.player_id WHERE r.force_id=$1 AND r.{column}>0 ORDER BY r.{column} DESC,r.player_id LIMIT 200", c); cmd.Parameters.AddWithValue(force); await using var rd = await cmd.ExecuteReaderAsync(ct); var rank = 0; while (await rd.ReadAsync(ct)) result.Add(new(++rank, rd.GetInt64(0), rd.GetString(1), rd.GetInt64(2))); return result; }

    public async Task<NationTaskView> GetTaskAsync(long playerId, CancellationToken ct)
    { await using var c = await db.DataSource.OpenConnectionAsync(ct); var force = await ForceAsync(c, null, playerId, ct); await SettleTaskAsync(c, null, force, ct); int type; long target, progress; DateTimeOffset? end; bool won; await using (var cmd = new NpgsqlCommand("SELECT task_type,task_target,task_progress,task_ends_at,task_won FROM nation_forces WHERE force_id=$1", c)) { cmd.Parameters.AddWithValue(force); await using var r = await cmd.ExecuteReaderAsync(ct); await r.ReadAsync(ct); type = r.GetInt16(0); target = r.GetInt64(1); progress = r.GetInt64(2); end = r.IsDBNull(3) ? null : r.GetFieldValue<DateTimeOffset>(3); won = r.GetBoolean(4); } var score = await PlayerValueAsync(c, null, playerId, "task_score", ct); DateTimeOffset? available = null; await using (var cd = new NpgsqlCommand("SELECT invest_available_at FROM player_nation_ranks WHERE player_id=$1", c)) { cd.Parameters.AddWithValue(playerId); var value = await cd.ExecuteScalarAsync(ct); if (value is DateTimeOffset date) available = date; } return new(type, target, progress, end, won, score, available); }

    public async Task<IReadOnlyList<NationScheduledTaskView>> GetScheduledTasksAsync(long playerId,CancellationToken ct)
    {await using var c=await db.DataSource.OpenConnectionAsync(ct);var force=await ForceAsync(c,null,playerId,ct);var result=new List<NationScheduledTaskView>();await using var cmd=new NpgsqlCommand("SELECT id,task_type,task_id,target,progress,starts_at,ends_at,status,dependency_code,event_serial FROM nation_scheduled_tasks WHERE force_id=$1 ORDER BY starts_at DESC,id DESC LIMIT 20",c);cmd.Parameters.AddWithValue(force);await using var r=await cmd.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))result.Add(new(r.GetInt64(0),r.GetInt16(1),r.GetInt32(2),r.GetInt64(3),r.GetInt64(4),r.GetFieldValue<DateTimeOffset>(5),r.GetFieldValue<DateTimeOffset>(6),r.GetInt16(7),r.GetString(8),r.GetInt32(9)));return result;}

    public async Task<NationTrialReward> ClaimScheduledRewardAsync(long playerId,string slotKey,CancellationToken ct)
    {await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);var force=await ForceAsync(c,t,playerId,ct);int type,level,order=0;await using(var task=new NpgsqlCommand("SELECT s.task_type,f.level,CASE WHEN s.task_type=9 THEN s.event_serial ELSE 0 END FROM nation_scheduled_tasks s JOIN nation_forces f ON f.force_id=s.force_id WHERE s.slot_key=$1 AND s.force_id=$2 AND s.status IN(1,3) ORDER BY s.event_serial DESC,s.id DESC LIMIT 1 FOR UPDATE OF s",c,t)){task.Parameters.AddWithValue(slotKey);task.Parameters.AddWithValue(force);await using var r=await task.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("NATION_TASK_REWARD_UNAVAILABLE","Scheduled Nation task is not resolved.");type=r.GetInt16(0);level=r.GetInt32(1);order=r.GetInt32(2);}await using(var active=new NpgsqlCommand("SELECT 1 FROM nation_scheduled_tasks WHERE slot_key=$1 AND force_id=$2 AND status=0",c,t)){active.Parameters.AddWithValue(slotKey);active.Parameters.AddWithValue(force);if(await active.ExecuteScalarAsync(ct)is not null)throw new GameException("NATION_TASK_REWARD_UNAVAILABLE","Scheduled Nation task still has an active round.");}if(type==6){await using var finalRound=new NpgsqlCommand("SELECT COALESCE(max(event_serial),0) FROM nation_scheduled_tasks WHERE slot_key=$1 AND force_id=$2 AND task_type=6 AND status IN(1,3)",c,t);finalRound.Parameters.AddWithValue(slotKey);finalRound.Parameters.AddWithValue(force);if(Convert.ToInt32(await finalRound.ExecuteScalarAsync(ct))<3)throw new GameException("NATION_TASK_REWARD_UNAVAILABLE","Expansion task has not completed all three legacy rounds.");}if(type is 2 or 3 or 4){await using var nationRank=new NpgsqlCommand("SELECT 1+count(*) FROM (SELECT force_id,sum(progress) score FROM nation_scheduled_tasks WHERE slot_key=$1 AND task_type=$2 GROUP BY force_id) x WHERE x.score>(SELECT sum(progress) FROM nation_scheduled_tasks WHERE slot_key=$1 AND task_type=$2 AND force_id=$3)",c,t);nationRank.Parameters.AddWithValue(slotKey);nationRank.Parameters.AddWithValue(type);nationRank.Parameters.AddWithValue(force);order=Convert.ToInt32(await nationRank.ExecuteScalarAsync(ct));}if(type==5){await using var maxLv=new NpgsqlCommand("SELECT max(level) FROM nation_forces",c,t);level=Convert.ToInt32(await maxLv.ExecuteScalarAsync(ct));order=1;}var scores=new List<(long player,long score)>();await using(var ranked=new NpgsqlCommand("SELECT player_id,sum(value) FROM (SELECT e.player_id,e.event_key,max(e.value) value FROM nation_task_events e JOIN nation_scheduled_tasks s ON s.id=e.task_id WHERE s.slot_key=$1 AND s.force_id=$2 AND e.player_id IS NOT NULL GROUP BY e.player_id,e.event_key) x GROUP BY player_id ORDER BY sum(value) DESC,player_id",c,t)){ranked.Parameters.AddWithValue(slotKey);ranked.Parameters.AddWithValue(force);await using var r=await ranked.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))scores.Add((r.GetInt64(0),r.GetInt64(1)));}var index=scores.FindIndex(x=>x.player==playerId);if(index<0)throw new GameException("NATION_TASK_NOT_PARTICIPATED","Player did not contribute to this task.");var rank=1+scores.Take(index).Count(x=>x.score>scores[index].score);if(!content.NationTaskRankingRewards.TryGetValue(type,out var table))throw new GameException("NATION_TASK_REWARD_STATIC_MISSING","Nation task ranking table is missing.",500);var reward=table.FirstOrDefault(x=>x.KingdomLevel==level&&rank>=x.HighRank&&rank<=x.LowRank&&(type is not(2 or 3 or 4)||x.TaskOrder==order)&&(type!=5||x.TaskOrder==1)&&(type!=9||x.Period==Math.Max(1,order)))??throw new GameException("NATION_TASK_REWARD_STATIC_MISSING","No matching legacy Nation task ranking reward.",500);var rewardExp=reward.Exp;var rewardIron=reward.Iron;if(type==6){int balance;await using(var b=new NpgsqlCommand("SELECT balance_before FROM nation_scheduled_tasks WHERE slot_key=$1 AND force_id=$2 AND task_type=6 ORDER BY event_serial DESC LIMIT 1",c,t)){b.Parameters.AddWithValue(slotKey);b.Parameters.AddWithValue(force);balance=Convert.ToInt32(await b.ExecuteScalarAsync(ct));}var tr=content.NationExpansionTargets.FirstOrDefault(x=>x.Win==balance);var sr=content.NationExpansionPeriods.OrderByDescending(x=>x.Id).First();var rate=(tr?.RewardRate??1)*sr.RewardRate;rewardExp=(int)(rewardExp*rate);rewardIron=(int)(rewardIron*rate);}await using(var claim=new NpgsqlCommand("INSERT INTO nation_scheduled_reward_claims(slot_key,player_id,task_type,rank,exp,iron) VALUES($1,$2,$3,$4,$5,$6) ON CONFLICT DO NOTHING",c,t)){claim.Parameters.AddWithValue(slotKey);claim.Parameters.AddWithValue(playerId);claim.Parameters.AddWithValue(type);claim.Parameters.AddWithValue(rank);claim.Parameters.AddWithValue(rewardExp);claim.Parameters.AddWithValue(rewardIron);if(await claim.ExecuteNonQueryAsync(ct)!=1)throw new GameException("NATION_TASK_REWARD_RECEIVED","Scheduled Nation task reward was already claimed.",409);}await experience.AddAsync(c,t,playerId,rewardExp,ct);await using(var iron=new NpgsqlCommand("UPDATE player_resources SET iron=iron+$2 WHERE player_id=$1",c,t)){iron.Parameters.AddWithValue(playerId);iron.Parameters.AddWithValue(rewardIron);await iron.ExecuteNonQueryAsync(ct);}await ironActivity.RecordGainAsync(c,t,playerId,rewardIron,ct);await t.CommitAsync(ct);return new(0,0,rewardExp,rewardIron);}

    public async Task<NationTaskView> StartUpgradeTaskAsync(long playerId, CancellationToken ct)
    { await using var c = await db.DataSource.OpenConnectionAsync(ct); await using var t = await c.BeginTransactionAsync(ct); var force = await ForceAsync(c, t, playerId, ct); int building = 0; await using (var m = new NpgsqlCommand("SELECT building_id FROM player_office_memberships WHERE player_id=$1 AND state=1", c, t)) { m.Parameters.AddWithValue(playerId); var value = await m.ExecuteScalarAsync(ct); if (value is not null) building = Convert.ToInt32(value); } if (building is not (1 or 3)) throw new GameException("UPGRADE_OFFICIAL_FORBIDDEN", "Only legacy office 1 or 3 may start nation upgrade.", 403); int level, stage; long exp; DateTimeOffset? end; await using (var f = new NpgsqlCommand("SELECT level,stage,exp,task_ends_at FROM nation_forces WHERE force_id=$1 FOR UPDATE", c, t)) { f.Parameters.AddWithValue(force); await using var r = await f.ExecuteReaderAsync(ct); await r.ReadAsync(ct); level = r.GetInt32(0); stage = r.GetInt16(1); exp = r.GetInt64(2); end = r.IsDBNull(3) ? null : r.GetFieldValue<DateTimeOffset>(3); } var now = DateTimeOffset.UtcNow; if (end > now) throw new GameException("NATION_TASK_ACTIVE", "Nation task is active."); if (end.HasValue && end.Value.AddHours(20) > now) throw new GameException("NATION_TASK_COOLDOWN", "Nation upgrade is in its legacy 20-hour cooldown."); if (stage < 4) throw new GameException("UPGRADE_TRIAL_ACTIVE", "Nation trial must finish first."); if (!content.KingdomLevels.TryGetValue(level, out var kingdom) || level >= content.KingdomLevels.Keys.Max()) throw new GameException("NATION_MAX_LEVEL", "Nation is at maximum level."); if (exp < kingdom.UpgradeExp) throw new GameException("NATION_EXP_NOT_FULL", "Nation EXP is not full."); if (!content.Barbarians.TryGetValue(kingdom.BarbarianLevel, out var barbarian)) throw new GameException("BARBARIAN_STATIC_MISSING", "Nation upgrade barbarian data is missing.", 500); var taskEnd = now.AddHours(4); await using (var reset = new NpgsqlCommand("UPDATE nation_forces SET task_type=1,task_target=$2,task_progress=0,task_ends_at=$3,task_won=false,updated_at=now() WHERE force_id=$1;DELETE FROM nation_task_npcs WHERE force_id=$1;UPDATE player_nation_ranks SET task_score=0,task_received=false WHERE force_id=$1", c, t)) { reset.Parameters.AddWithValue(force); reset.Parameters.AddWithValue(barbarian.Target); reset.Parameters.AddWithValue(taskEnd); await reset.ExecuteNonQueryAsync(ct); } var armies = (force == 1 ? barbarian.WeiArmies : force == 2 ? barbarian.ShuArmies : barbarian.WuArmies).Split(';', StringSplitOptions.RemoveEmptyEntries).Select(int.Parse).ToArray(); if (armies.Length == 0) throw new GameException("BARBARIAN_ARMY_MISSING", "Nation upgrade army mapping is empty.", 500); for (var i = 0; i < barbarian.Num; i++) { var armyId = armies[i % armies.Length]; if (!content.Armies.TryGetValue(armyId, out var army)) continue; await using var add = new NpgsqlCommand("INSERT INTO nation_task_npcs(force_id,city_id,army_id,hp_value) VALUES($1,$2,$3,$4)", c, t); add.Parameters.AddWithValue(force); add.Parameters.AddWithValue(TrialCities[force]); add.Parameters.AddWithValue(armyId); add.Parameters.AddWithValue(army.ArmyHp); await add.ExecuteNonQueryAsync(ct); } await t.CommitAsync(ct); return await GetTaskAsync(playerId, ct); }

    public async Task RecordTaskDamageAsync(NpgsqlConnection c, NpgsqlTransaction t, long playerId, int cityId, int damage, bool defeated, CancellationToken ct)
    { if (damage <= 0) return; int force = await ForceAsync(c, t, playerId, ct); long target, progress; int type; DateTimeOffset? end; await using (var f = new NpgsqlCommand("SELECT task_type,task_target,task_progress,task_ends_at FROM nation_forces WHERE force_id=$1 FOR UPDATE", c, t)) { f.Parameters.AddWithValue(force); await using var r = await f.ExecuteReaderAsync(ct); await r.ReadAsync(ct); type = r.GetInt16(0); target = r.GetInt64(1); progress = r.GetInt64(2); end = r.IsDBNull(3) ? null : r.GetFieldValue<DateTimeOffset>(3); } if (type != 1 || end <= DateTimeOffset.UtcNow) return; var applied = (int)Math.Min(damage, Math.Max(0, target - progress)); if (applied <= 0) return; progress += applied; await using (var rank = new NpgsqlCommand("INSERT INTO player_nation_ranks(player_id,force_id,task_score,task_received) VALUES($1,$2,$3,false) ON CONFLICT(player_id) DO UPDATE SET force_id=$2,task_score=player_nation_ranks.task_score+$3,task_received=false", c, t)) { rank.Parameters.AddWithValue(playerId); rank.Parameters.AddWithValue(force); rank.Parameters.AddWithValue(applied); await rank.ExecuteNonQueryAsync(ct); } if (progress >= target) { int level; long exp; await using (var current = new NpgsqlCommand("SELECT level,exp FROM nation_forces WHERE force_id=$1", c, t)) { current.Parameters.AddWithValue(force); await using var r = await current.ExecuteReaderAsync(ct); await r.ReadAsync(ct); level = r.GetInt32(0); exp = r.GetInt64(1); } var cost = content.KingdomLevels[level].UpgradeExp; await using var win = new NpgsqlCommand("UPDATE nation_forces SET level=level+1,exp=GREATEST(0,exp-$3),task_progress=$2,task_won=true,updated_at=now() WHERE force_id=$1", c, t); win.Parameters.AddWithValue(force); win.Parameters.AddWithValue(progress); win.Parameters.AddWithValue(cost); await win.ExecuteNonQueryAsync(ct); } else { await using var save = new NpgsqlCommand("UPDATE nation_forces SET task_progress=$2,updated_at=now() WHERE force_id=$1", c, t); save.Parameters.AddWithValue(force); save.Parameters.AddWithValue(progress); await save.ExecuteNonQueryAsync(ct); } }

    public async Task<NationInvestmentReward> InvestAsync(long playerId, CancellationToken ct)
    { await using var c = await db.DataSource.OpenConnectionAsync(ct); await using var t = await c.BeginTransactionAsync(ct); var force = await ForceAsync(c, t, playerId, ct); int level,eventId; long target, progress; int type; DateTimeOffset? end, available; await using (var p = new NpgsqlCommand("SELECT p.level,f.task_type,f.task_target,f.task_progress,f.task_ends_at,r.invest_available_at,f.task_event_serial FROM players p JOIN nation_forces f ON f.force_id=p.force_id LEFT JOIN player_nation_ranks r ON r.player_id=p.id WHERE p.id=$1 FOR UPDATE OF p,f", c, t)) { p.Parameters.AddWithValue(playerId); await using var r = await p.ExecuteReaderAsync(ct); await r.ReadAsync(ct); level = r.GetInt32(0); type = r.GetInt16(1); target = r.GetInt64(2); progress = r.GetInt64(3); end = r.IsDBNull(4) ? null : r.GetFieldValue<DateTimeOffset>(4); available = r.IsDBNull(5) ? null : r.GetFieldValue<DateTimeOffset>(5); eventId=r.GetInt32(6); } if (level < 30) throw new GameException("INVEST_LEVEL_LOCKED", "Investment opens at player level 30."); if (type != 4 || end <= DateTimeOffset.UtcNow) throw new GameException("INVEST_TASK_INACTIVE", "Legacy investment task is not active."); var now = DateTimeOffset.UtcNow; if (available > now) throw new GameException("INVEST_COOLDOWN", "Investment is in cooldown."); var elapsed = (end!.Value.AddMinutes(-90) - now).Negate().TotalMinutes; if (elapsed < 0 || elapsed >= 120) throw new GameException("INVEST_EVENT_INACTIVE", "No investment event is active."); var ev = content.InvestmentEvents.Where(x => x.S == eventId && x.T <= elapsed).OrderBy(x => x.T).LastOrDefault() ?? throw new GameException("INVEST_EVENT_MISSING", "Investment event static data is missing.", 500); if (progress + ev.Cc > target) throw new GameException("INVEST_TARGET_FULL", "Nation investment target is full."); var useDouble = progress + 2L * ev.Cc <= target && await items.ConsumeAsync(c,t,playerId,401,5,1,ct); var extraCopper=useDouble?ev.Cc:0; var extraExp=useDouble?ev.Er:0; await using (var consume = new NpgsqlCommand("UPDATE player_resources SET copper=copper-$2 WHERE player_id=$1 AND copper>=$2", c, t)) { consume.Parameters.AddWithValue(playerId); consume.Parameters.AddWithValue(ev.Cc); if (await consume.ExecuteNonQueryAsync(ct) != 1) throw new GameException("COPPER_NOT_ENOUGH", "Not enough copper."); } var next = (available > now ? available.Value : now).AddSeconds(ev.Cd); await using (var save = new NpgsqlCommand("UPDATE nation_forces SET task_progress=task_progress+$3 WHERE force_id=$2;UPDATE nation_scheduled_tasks SET progress=progress+$3 WHERE force_id=$2 AND task_type=4 AND status=0;INSERT INTO nation_task_events(task_id,event_key,player_id,value) SELECT id,concat('invest:',$1,':',$4::text),$1,$3 FROM nation_scheduled_tasks WHERE force_id=$2 AND task_type=4 AND status=0 ON CONFLICT DO NOTHING;INSERT INTO player_nation_ranks(player_id,force_id,task_score,task_received,invest_available_at) VALUES($1,$2,$3,false,$4) ON CONFLICT(player_id) DO UPDATE SET force_id=$2,task_score=player_nation_ranks.task_score+$3,task_received=false,invest_available_at=$4", c, t)) { save.Parameters.AddWithValue(playerId); save.Parameters.AddWithValue(force); save.Parameters.AddWithValue(ev.Cc+extraCopper); save.Parameters.AddWithValue(next); await save.ExecuteNonQueryAsync(ct); } await experience.AddAsync(c, t, playerId, ev.Er+extraExp, ct); await t.CommitAsync(ct); return new(ev.Cc, extraCopper, ev.Er, extraExp, next); }

