    static async Task ResolveCompetitionAsync(NpgsqlConnection c,NpgsqlTransaction t,int winner,int city,CancellationToken ct)
    {var slots=new List<string>();await using(var find=new NpgsqlCommand("SELECT DISTINCT slot_key FROM nation_scheduled_tasks WHERE task_type=1 AND target=$1 AND status=0 AND starts_at<=now() AND ends_at>now()",c,t)){find.Parameters.AddWithValue(city);await using var r=await find.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))slots.Add(r.GetString(0));}foreach(var slot in slots){await using var finish=new NpgsqlCommand("UPDATE nation_scheduled_tasks SET status=CASE WHEN force_id=$2 THEN 1 ELSE 3 END,dependency_code=CASE WHEN force_id=$2 THEN 'result:won' ELSE 'result:lost' END WHERE slot_key=$1 AND task_type=1 AND status=0",c,t);finish.Parameters.AddWithValue(slot);finish.Parameters.AddWithValue(winner);await finish.ExecuteNonQueryAsync(ct);}}

    public async Task AddScoreAsync(NpgsqlConnection c,NpgsqlTransaction t,long playerId,int force,int cityId,int kind,string eventKey,CancellationToken ct)
    {var amount=kind switch{1=>5,2=>2,_=>1};await using(var ledger=new NpgsqlCommand("INSERT INTO player_score_events(player_id,event_key,score) VALUES($1,$2,$3) ON CONFLICT(player_id,event_key) DO NOTHING",c,t)){ledger.Parameters.AddWithValue(playerId);ledger.Parameters.AddWithValue(eventKey);ledger.Parameters.AddWithValue(amount);if(await ledger.ExecuteNonQueryAsync(ct)!=1)return;}await using(var score=new NpgsqlCommand("INSERT INTO player_scores(player_id,occupy_count,assist_count,cheer_count,score) VALUES($1,$2,$3,$4,$5) ON CONFLICT(player_id) DO UPDATE SET occupy_count=player_scores.occupy_count+$2,assist_count=player_scores.assist_count+$3,cheer_count=player_scores.cheer_count+$4,score=player_scores.score+$5",c,t)){score.Parameters.AddWithValue(playerId);score.Parameters.AddWithValue(kind==1?1:0);score.Parameters.AddWithValue(kind==2?1:0);score.Parameters.AddWithValue(kind is not(1 or 2)?1:0);score.Parameters.AddWithValue(amount);await score.ExecuteNonQueryAsync(ct);}await dragon.RecordScoreAsync(c,t,playerId,kind,ct);await ApplyScheduledEventAsync(c,t,force,playerId,eventKey,[5],amount,ct);}

    async Task ApplyScheduledEventAsync(NpgsqlConnection c,NpgsqlTransaction t,int force,long? playerId,string eventKey,int[] types,long value,CancellationToken ct)
    {if(value<=0)return;var tasks=new List<long>();await using(var find=new NpgsqlCommand("SELECT id FROM nation_scheduled_tasks WHERE force_id=$1 AND status=0 AND task_type=ANY($2) AND starts_at<=now() AND ends_at>now() FOR UPDATE",c,t)){find.Parameters.AddWithValue(force);find.Parameters.AddWithValue(types);await using var r=await find.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))tasks.Add(r.GetInt64(0));}foreach(var task in tasks){await using var add=new NpgsqlCommand("INSERT INTO nation_task_events(task_id,event_key,player_id,value) VALUES($1,$2,$3,$4) ON CONFLICT DO NOTHING",c,t);add.Parameters.AddWithValue(task);add.Parameters.AddWithValue(eventKey);add.Parameters.AddWithValue((object?)playerId??DBNull.Value);add.Parameters.AddWithValue(value);if(await add.ExecuteNonQueryAsync(ct)!=1)continue;await using var progress=new NpgsqlCommand("UPDATE nation_scheduled_tasks SET progress=progress+$2 WHERE id=$1;INSERT INTO player_nation_ranks(player_id,force_id,task_score,task_received) SELECT $3,$4,$2,false WHERE $3 IS NOT NULL ON CONFLICT(player_id) DO UPDATE SET force_id=$4,task_score=player_nation_ranks.task_score+$2,task_received=false",c,t);progress.Parameters.AddWithValue(task);progress.Parameters.AddWithValue(value);progress.Parameters.AddWithValue((object?)playerId??DBNull.Value);progress.Parameters.AddWithValue(force);await progress.ExecuteNonQueryAsync(ct);}}

    async Task SetAbsoluteScheduledProgressAsync(NpgsqlConnection c,NpgsqlTransaction t,int force,long playerId,string eventKey,int type,long absolute,CancellationToken ct)
    {long task,old;await using(var find=new NpgsqlCommand("SELECT id,progress FROM nation_scheduled_tasks WHERE force_id=$1 AND task_type=$2 AND status=0 AND starts_at<=now() AND ends_at>now() FOR UPDATE",c,t)){find.Parameters.AddWithValue(force);find.Parameters.AddWithValue(type);await using var r=await find.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))return;task=r.GetInt64(0);old=r.GetInt64(1);}if(absolute<=old)return;var delta=absolute-old;await using var add=new NpgsqlCommand("INSERT INTO nation_task_events(task_id,event_key,player_id,value) VALUES($1,$2,$3,$4) ON CONFLICT DO NOTHING",c,t);add.Parameters.AddWithValue(task);add.Parameters.AddWithValue(eventKey);add.Parameters.AddWithValue(playerId);add.Parameters.AddWithValue(delta);if(await add.ExecuteNonQueryAsync(ct)!=1)return;await using var save=new NpgsqlCommand("UPDATE nation_scheduled_tasks SET progress=$2 WHERE id=$1;INSERT INTO player_nation_ranks(player_id,force_id,task_score,task_received) VALUES($3,$4,$5,false) ON CONFLICT(player_id) DO UPDATE SET force_id=$4,task_score=player_nation_ranks.task_score+$5,task_received=false",c,t);save.Parameters.AddWithValue(task);save.Parameters.AddWithValue(absolute);save.Parameters.AddWithValue(playerId);save.Parameters.AddWithValue(force);save.Parameters.AddWithValue(delta);await save.ExecuteNonQueryAsync(ct);}

