    public async Task<NationTrialReward> ClaimProtectionRewardAsync(long playerId,CancellationToken ct)
    {await using var c=await db.DataSource.OpenConnectionAsync(ct);await using var t=await c.BeginTransactionAsync(ct);var force=await ForceAsync(c,t,playerId,ct);int id;bool won;await using(var task=new NpgsqlCommand("SELECT trial_id,COALESCE(won,false) FROM nation_protections WHERE force_id=$1 FOR UPDATE",c,t)){task.Parameters.AddWithValue(force);await using var r=await task.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("PROTECTION_NOT_ACTIVE","Nation has no protection task.");id=r.GetInt32(0);won=r.GetBoolean(1);}if(!won||!content.CdExams.TryGetValue(id,out var exam))throw new GameException("PROTECTION_NOT_WON","Protection task was not won.");int kills;bool received;await using(var p=new NpgsqlCommand("SELECT protect_kills,protect_received FROM player_nation_ranks WHERE player_id=$1 FOR UPDATE",c,t)){p.Parameters.AddWithValue(playerId);await using var r=await p.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new GameException("PROTECTION_NOT_JOINED","Player did not join protection.");kills=r.GetInt32(0);received=r.GetBoolean(1);}if(kills<=0)throw new GameException("PROTECTION_NOT_JOINED","Player did not join protection.");if(received)throw new GameException("PROTECTION_REWARD_RECEIVED","Protection reward was already received.");var rank=await RankAsync(c,t,force,"protect_kills",playerId,ct);var rate=content.CdExamRankings.FirstOrDefault(x=>x.High<=rank&&rank<=x.Low)?.E??0;var exp=(int)(exam.ProtectRankingExp*rate);var iron=(int)(exam.ProtectRankingIron*rate);await experience.AddAsync(c,t,playerId,exp,ct);await using(var reward=new NpgsqlCommand("UPDATE player_resources SET iron=iron+$2 WHERE player_id=$1;UPDATE player_nation_ranks SET protect_received=true WHERE player_id=$1",c,t)){reward.Parameters.AddWithValue(playerId);reward.Parameters.AddWithValue(iron);await reward.ExecuteNonQueryAsync(ct);}await ironActivity.RecordGainAsync(c,t,playerId,iron,ct);await t.CommitAsync(ct);return new(0,0,exp,iron);}

