    public async Task RecordTrialKillAsync(NpgsqlConnection c, NpgsqlTransaction t, long playerId, int cityId, int count, CancellationToken ct)
    { if (count <= 0) return; int force; await using (var p = new NpgsqlCommand("SELECT force_id FROM players WHERE id=$1", c, t)) { p.Parameters.AddWithValue(playerId); force = Convert.ToInt32(await p.ExecuteScalarAsync(ct)); } if (force is < 1 or > 3) return; int id, stage, total; DateTimeOffset? end; await using (var f = new NpgsqlCommand("SELECT trial_id,stage,trial_general_kills,trial_ends_at FROM nation_forces WHERE force_id=$1 FOR UPDATE", c, t)) { f.Parameters.AddWithValue(force); await using var r = await f.ExecuteReaderAsync(ct); await r.ReadAsync(ct); id = r.GetInt32(0); stage = r.GetInt16(1); total = r.GetInt32(2); end = r.IsDBNull(3) ? null : r.GetFieldValue<DateTimeOffset>(3); } if (stage >= 4 || end <= DateTimeOffset.UtcNow || !content.CdExams.TryGetValue(id, out var exam)) return; await using (var npc = new NpgsqlCommand("UPDATE nation_trial_npcs SET defeated=true WHERE id IN(SELECT id FROM nation_trial_npcs WHERE force_id=$1 AND city_id=$2 AND defeated=false ORDER BY id LIMIT $3)", c, t)) { npc.Parameters.AddWithValue(force); npc.Parameters.AddWithValue(cityId); npc.Parameters.AddWithValue(count); if (await npc.ExecuteNonQueryAsync(ct) <= 0) return; } await using (var rank = new NpgsqlCommand("INSERT INTO player_nation_ranks(player_id,force_id,trial_kills,trial_received) VALUES($1,$2,$3,false) ON CONFLICT(player_id) DO UPDATE SET force_id=$2,trial_kills=player_nation_ranks.trial_kills+$3,trial_received=false", c, t)) { rank.Parameters.AddWithValue(playerId); rank.Parameters.AddWithValue(force); rank.Parameters.AddWithValue(count); await rank.ExecuteNonQueryAsync(ct); } total += count; var threshold = stage switch { 0 => exam.Open1, 1 => exam.Open2, 2 => exam.Open3, _ => exam.General0 + exam.General1 + exam.General2 }; if (total >= threshold) { stage++; if (stage < 4) await SpawnStageAsync(c, t, force, exam, stage, ct); } await using (var save = new NpgsqlCommand("UPDATE nation_forces SET trial_general_kills=$2,stage=$3,trial_won=($3>=4),trial_ends_at=CASE WHEN $3>=4 THEN now() ELSE trial_ends_at END,updated_at=now() WHERE force_id=$1", c, t)) { save.Parameters.AddWithValue(force); save.Parameters.AddWithValue(total); save.Parameters.AddWithValue(stage); await save.ExecuteNonQueryAsync(ct); } }

    async Task SpawnStageAsync(NpgsqlConnection c, NpgsqlTransaction t, int force, CdExamDefinition e, int stage, CancellationToken ct)
    { var cities = stage == 0 ? TrialCities[force].ToString() : force switch { 1 => stage == 1 ? e.WeiCities1 : stage == 2 ? e.WeiCities2 : e.WeiCities3, 2 => stage == 1 ? e.ShuCities1 : stage == 2 ? e.ShuCities2 : e.ShuCities3, _ => stage == 1 ? e.WuCities1 : stage == 2 ? e.WuCities2 : e.WuCities3 }; var armies = force switch { 1 => stage == 0 ? e.WeiArmies0 : stage == 1 ? e.WeiArmies1 : stage == 2 ? e.WeiArmies2 : e.WeiArmies3, 2 => stage == 0 ? e.ShuArmies0 : stage == 1 ? e.ShuArmies1 : stage == 2 ? e.ShuArmies2 : e.ShuArmies3, _ => stage == 0 ? e.WuArmies0 : stage == 1 ? e.WuArmies1 : stage == 2 ? e.WuArmies2 : e.WuArmies3 }; var cityIds = cities.Split(';', StringSplitOptions.RemoveEmptyEntries).Select(int.Parse).ToArray(); var armyIds = armies.Split(';', StringSplitOptions.RemoveEmptyEntries).Select(int.Parse).ToArray(); var num = stage switch { 0 => e.General0, 1 => e.General1, 2 => e.General2, _ => e.General3 }; if (cityIds.Length == 0 || armyIds.Length == 0) throw new GameException("TRIAL_STATIC_INVALID", "Trial stage city or army mapping is empty.", 500); for (var i = 0; i < num; i++) { await using var add = new NpgsqlCommand("INSERT INTO nation_trial_npcs(force_id,trial_id,stage,city_id,army_id) VALUES($1,$2,$3,$4,$5)", c, t); add.Parameters.AddWithValue(force); add.Parameters.AddWithValue(e.Id); add.Parameters.AddWithValue(stage); add.Parameters.AddWithValue(cityIds[i % cityIds.Length]); add.Parameters.AddWithValue(armyIds[Random.Shared.Next(armyIds.Length)]); await add.ExecuteNonQueryAsync(ct); } }
    static async Task ExpireTrialAsync(NpgsqlConnection c, NpgsqlTransaction? t, int force, CancellationToken ct) { await using var cmd = new NpgsqlCommand("UPDATE nation_forces SET stage=4,trial_won=false,updated_at=now() WHERE force_id=$1 AND stage<4 AND trial_ends_at<=now()", c, t); cmd.Parameters.AddWithValue(force); await cmd.ExecuteNonQueryAsync(ct); }
    static async Task SettleTaskAsync(NpgsqlConnection c, NpgsqlTransaction? t, int force, CancellationToken ct) { await using var cmd = new NpgsqlCommand("UPDATE nation_forces SET task_won=(task_progress>=task_target),updated_at=now() WHERE force_id=$1 AND task_type<>0 AND task_ends_at<=now() AND task_won=false", c, t); cmd.Parameters.AddWithValue(force); await cmd.ExecuteNonQueryAsync(ct); }
    static async Task EnsureProtectionAsync(NpgsqlConnection c,NpgsqlTransaction t,int force,CancellationToken ct)
    {await using(var exists=new NpgsqlCommand("SELECT 1 FROM nation_protections WHERE force_id=$1",c,t)){exists.Parameters.AddWithValue(force);if(await exists.ExecuteScalarAsync(ct)is not null)return;}int attacking,id,city;DateTimeOffset end;await using(var active=new NpgsqlCommand("SELECT f.force_id,f.trial_id,n.city_id,f.trial_ends_at FROM nation_forces f JOIN nation_trial_npcs n ON n.force_id=f.force_id AND n.stage=3 AND n.defeated=false JOIN world_cities w ON w.city_id=n.city_id AND w.owner_force_id=$1 WHERE f.force_id<>$1 AND f.stage=3 AND f.trial_ends_at>now() ORDER BY n.id LIMIT 1",c,t)){active.Parameters.AddWithValue(force);await using var r=await active.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))return;attacking=r.GetInt16(0);id=r.GetInt32(1);city=r.GetInt32(2);end=r.GetFieldValue<DateTimeOffset>(3);}await using(var add=new NpgsqlCommand("INSERT INTO nation_protections(force_id,attacking_force_id,city_id,trial_id,ends_at) VALUES($1,$2,$3,$4,$5) ON CONFLICT(force_id) DO NOTHING;UPDATE player_nation_ranks SET protect_kills=0,protect_received=true WHERE force_id=$1",c,t)){add.Parameters.AddWithValue(force);add.Parameters.AddWithValue(attacking);add.Parameters.AddWithValue(city);add.Parameters.AddWithValue(id);add.Parameters.AddWithValue(end);await add.ExecuteNonQueryAsync(ct);}}
    static async Task<int> PlayerValueAsync(NpgsqlConnection c, NpgsqlTransaction? t, long player, string column, CancellationToken ct) { await using var cmd = new NpgsqlCommand($"SELECT COALESCE((SELECT {column} FROM player_nation_ranks WHERE player_id=$1),0)", c, t); cmd.Parameters.AddWithValue(player); return Convert.ToInt32(await cmd.ExecuteScalarAsync(ct)); }
    static async Task<bool> RewardFlagAsync(NpgsqlConnection c, NpgsqlTransaction? t, long player, string column, CancellationToken ct) { await using var cmd = new NpgsqlCommand($"SELECT COALESCE((SELECT {column} FROM player_nation_ranks WHERE player_id=$1),true)", c, t); cmd.Parameters.AddWithValue(player); return Convert.ToBoolean(await cmd.ExecuteScalarAsync(ct)); }
    static async Task<int> RankAsync(NpgsqlConnection c, NpgsqlTransaction? t, int force, string column, long player, CancellationToken ct) { await using var cmd = new NpgsqlCommand($"SELECT CASE WHEN me.{column}>0 THEN 1+(SELECT count(*) FROM player_nation_ranks x WHERE x.force_id=$2 AND x.{column}>me.{column}) ELSE 0 END FROM player_nation_ranks me WHERE me.player_id=$1", c, t); cmd.Parameters.AddWithValue(player); cmd.Parameters.AddWithValue(force); var value = await cmd.ExecuteScalarAsync(ct); return value is null ? 0 : Convert.ToInt32(value); }
    static async Task<int> ForceAsync(NpgsqlConnection c, NpgsqlTransaction? t, long player, CancellationToken ct) { await using var cmd = new NpgsqlCommand("SELECT force_id FROM players WHERE id=$1", c, t); cmd.Parameters.AddWithValue(player); var force = Convert.ToInt32(await cmd.ExecuteScalarAsync(ct)); if (force is < 1 or > 3) throw new GameException("NATION_NOT_CHOSEN", "Choose a nation first."); return force; }
}




